mapper.select:
SELECT id AS customer_id, 0::bigint AS member_id, name, email, status,
       updated_at, version, NULL::text AS tier
FROM customer

    AND updated_at >= #{fromDate}
    AND updated_at < #{toDate}
    AND status = #{status}

ORDER BY id

SELECT customer_id, member_id, name, email, status, updated_at, version, tier
FROM batch_customer_export
WHERE job_name=#{job} AND run_id=#{run} AND artifact=#{artifact}
  AND customer_id BETWEEN #{low} AND #{high}
ORDER BY customer_id, member_id

SELECT file_index, ordinal, reason
FROM batch_input_error WHERE job_name=#{job} AND run_id=#{run}
ORDER BY file_index, ordinal
